void GameFlowUi::toggleMenu() {if(menuOpen())panel_=Panel::Closed;else menuPanel(Panel::Main);}
bool GameFlowUi::scriptDialog() const {auto local=data_.session->localPlayer().value_or(0);for(auto& [id,d]:data_.session->dialogs())if(d->owners&(1u<<local))return true;return false;}
